input:
The first line contains one integer q (1 ≤ q ≤ 100000) — the number of events.

Then q lines follow. Each line describes the event:

  * 1 pi (1 ≤ pi ≤ 108) — one warrior with personality pi joins Vova's army; 
  * 2 pi (1 ≤ pi ≤ 108) — one warrior with personality pi leaves Vova's army (it is guaranteed that there is at least one such warrior in Vova's army by this moment); 
  * 3 pi li (1 ≤ pi, li ≤ 108) — Vova tries to hire a commander with personality pi and leadership li. There is at least one event of this type.

standard_solution_code:
import sys
from collections import defaultdict

class Node:

	def __init__(self, val):
		self.val = val
		self.left = None
		self.right = None
q = int(sys.stdin.readline())
root = Node(0)
for _ in range(q):
	l = list(map(int, sys.stdin.readline().split()))
	if l[0] == 1:
		bit = 28
		cur = root
		num = l[1]
		while bit >= 0:
			if 1 << bit & num == 1 << bit:
				if cur.right is None:
					cur.right = Node(1)
				else:
					cur.right.val += 1
				cur = cur.right
			else:
				if cur.left is None:
					cur.left = Node(1)
				else:
					cur.left.val += 1
				cur = cur.left
			bit -= 1
	if l[0] == 2:
		num = l[1]
		(bit, cur) = (28, root)
		while bit >= 0:
			if 1 << bit & num == 1 << bit:
				cur.right.val -= 1
				cur = cur.right
			else:
				cur.left.val -= 1
				cur = cur.left
			bit -= 1
	if l[0] == 3:
		(res, cur, bit) = (0, root, 28)
		while bit >= 0:
			num = 1 << bit
			if num & l[2] and num & l[1]:
				if cur.right is not None:
					res += cur.right.val
				if cur.left is None:
					break
				cur = cur.left
				bit -= 1
				continue
			if num & l[2] and (not num & l[1]):
				if cur.left is not None:
					res += cur.left.val
				if cur.right is None:
					break
				cur = cur.right
				bit -= 1
				continue
			if not num & l[2] and num & l[1]:
				if cur.right is None:
					break
				cur = cur.right
				bit -= 1
				continue
			if not num & l[2] and (not num & l[1]):
				if cur.left is None:
					break
				cur = cur.left
				bit -= 1
				continue
		print(res)
